mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY ANNIVERSARY_GUBUN DESC, ANNIVER_STARTDAY ASC, ANNIVERSARY_TIME ASC, ANNIVER_ORDER ASC) AS RNUM, TB.* FROM ( SELECT A.BROD_ANNSEQ, A.BROD_CODE, A.ATCH_FILE_ID, A.ANNIVERSARY_GUBUN, A.ANNIVERSARY_TIME, A.ANNIVER_STARTDAY AS ANNIVERSTARTDAY, A.ANNIVER_ENDDAY AS anniverEndDay, A.ANNIVER_ORDER, B.ORIGNL_FILE_NM AS orignlFileNm, B.PLAY_TIME AS playTime, B.FILE_THUMNAIL AS fileThumnail, C.CODE_NM AS codeNm, A.ANNIVER_NAME AS anniverName, A.ANNIVERSARY_STARTTIME AS anniversaryStartTime FROM TB_BRODANNIVERSARY A JOIN LETTNFILEDETAIL B ON A.ATCH_FILE_ID = B.ATCH_FILE_ID JOIN LETTCCMMNDETAILCODE C ON A.ANNIVERSARY_GUBUN = C.CODE WHERE A.BROD_CODE = #{brodCode}
AND #{brodDay} BETWEEN A.ANNIVER_STARTDAY AND A.ANNIVER_ENDDAY
) TB ) TA WHERE 1=1
